from __future__ import annotations

from typing import Any

from models import TokenRecord, to_public_dict
from time_utils import (
    clamp_reference_now,
    format_debug_window,
    is_issued_too_far_in_future,
    is_token_older_than_max_age,
    summarize_time_checks,
)
from token_store import InMemoryTokenStore


def _deny(reason: str, token: TokenRecord | None = None, debug: str | None = None) -> dict[str, Any]:
    payload: dict[str, Any] = {"ok": False, "reason": reason}
    if token is not None:
        payload["token"] = to_public_dict(token)
    if debug is not None:
        payload["debug"] = debug
    return payload


def _allow(token: TokenRecord, details: dict[str, Any] | None = None) -> dict[str, Any]:
    payload: dict[str, Any] = {"ok": True, "reason": "authorized", "token": to_public_dict(token)}
    if details:
        payload["details"] = details
    return payload


def authorize_request(
    token_id: str,
    store: InMemoryTokenStore,
    reference_now_epoch: int | None = None,
    required_scope: str = "read",
) -> dict[str, Any]:
    now_epoch_value = clamp_reference_now(reference_now_epoch)
    token = store.get(token_id)
    if token is None:
        return _deny("token_not_found")

    if token.revoked:
        return _deny("token_revoked", token=token)

    if token.scope not in {"read", "write", "admin"}:
        return _deny("invalid_scope_on_token", token=token)

    if required_scope == "write" and token.scope not in {"write", "admin"}:
        return _deny("insufficient_scope", token=token)
    if required_scope == "admin" and token.scope != "admin":
        return _deny("insufficient_scope", token=token)

    if is_issued_too_far_in_future(token.issued_at_epoch, now_epoch_value):
        return _deny("token_not_yet_valid", token=token)

    if is_token_older_than_max_age(token.issued_at_epoch, now_epoch_value):
        return _deny("token_too_old", token=token)

    # BUG: comparison direction is inverted through summarize_time_checks usage.
    checks = summarize_time_checks(token.issued_at_epoch, token.expires_at_epoch, now_epoch_value)
    if checks["seconds_until_expiry"] > 0:
        debug = format_debug_window(token.issued_at_epoch, token.expires_at_epoch, now_epoch_value)
        return _deny("token_expired", token=token, debug=debug)

    return _allow(
        token,
        details={
            "required_scope": required_scope,
            "seconds_until_expiry": checks["seconds_until_expiry"],
        },
    )


def batch_authorize(
    token_ids: list[str],
    store: InMemoryTokenStore,
    reference_now_epoch: int | None = None,
    required_scope: str = "read",
) -> dict[str, Any]:
    now_epoch_value = clamp_reference_now(reference_now_epoch)
    results: list[dict[str, Any]] = []
    accepted = 0
    denied = 0

    for token_id in token_ids:
        result = authorize_request(
            token_id=token_id,
            store=store,
            reference_now_epoch=now_epoch_value,
            required_scope=required_scope,
        )
        results.append({"token_id": token_id, "result": result})
        if result.get("ok"):
            accepted += 1
        else:
            denied += 1

    return {
        "accepted": accepted,
        "denied": denied,
        "results": results,
    }

