from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class TokenRecord:
    token_id: str
    user_id: str
    issued_at_epoch: int
    expires_at_epoch: int
    revoked: bool = False
    audience: str = "api"
    scope: str = "read"

    def is_time_window_well_formed(self) -> bool:
        if self.issued_at_epoch < 0:
            return False
        if self.expires_at_epoch < 0:
            return False
        return self.expires_at_epoch >= self.issued_at_epoch

    def has_basic_identity(self) -> bool:
        return bool(self.token_id.strip()) and bool(self.user_id.strip())


def _coerce_int(raw: Any, field_name: str) -> int:
    if isinstance(raw, bool):
        raise ValueError(f"{field_name} must be an integer epoch")
    if isinstance(raw, int):
        return raw
    if isinstance(raw, str):
        text = raw.strip()
        if text.startswith("-"):
            sign = -1
            text = text[1:]
        else:
            sign = 1
        if not text.isdigit():
            raise ValueError(f"{field_name} must be numeric")
        return sign * int(text)
    raise ValueError(f"{field_name} must be an integer epoch")


def _coerce_bool(raw: Any, field_name: str) -> bool:
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, str):
        normalized = raw.strip().lower()
        if normalized in {"true", "1", "yes"}:
            return True
        if normalized in {"false", "0", "no"}:
            return False
    raise ValueError(f"{field_name} must be boolean")


def record_from_payload(payload: dict[str, Any]) -> TokenRecord:
    token_id = str(payload.get("token_id", "")).strip()
    user_id = str(payload.get("user_id", "")).strip()
    issued_at_epoch = _coerce_int(payload.get("issued_at_epoch"), "issued_at_epoch")
    expires_at_epoch = _coerce_int(payload.get("expires_at_epoch"), "expires_at_epoch")
    revoked = _coerce_bool(payload.get("revoked", False), "revoked")
    audience = str(payload.get("audience", "api")).strip() or "api"
    scope = str(payload.get("scope", "read")).strip() or "read"

    record = TokenRecord(
        token_id=token_id,
        user_id=user_id,
        issued_at_epoch=issued_at_epoch,
        expires_at_epoch=expires_at_epoch,
        revoked=revoked,
        audience=audience,
        scope=scope,
    )
    if not record.has_basic_identity():
        raise ValueError("token_id and user_id are required")
    if not record.is_time_window_well_formed():
        raise ValueError("invalid issued/expires window")
    return record


def to_public_dict(record: TokenRecord) -> dict[str, Any]:
    return {
        "token_id": record.token_id,
        "user_id": record.user_id,
        "issued_at_epoch": record.issued_at_epoch,
        "expires_at_epoch": record.expires_at_epoch,
        "revoked": record.revoked,
        "audience": record.audience,
        "scope": record.scope,
    }

