from __future__ import annotations

from datetime import datetime, timezone
from typing import Final


MAX_CLOCK_SKEW_SECONDS: Final[int] = 30
MAX_TOKEN_AGE_SECONDS: Final[int] = 60 * 60 * 24 * 14


def now_epoch() -> int:
    return int(datetime.now(timezone.utc).timestamp())


def parse_iso8601_to_epoch(value: str) -> int:
    text = value.strip()
    if not text:
        raise ValueError("empty timestamp")
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        raise ValueError("timestamp must be timezone-aware")
    return int(dt.timestamp())


def is_issued_too_far_in_future(issued_at_epoch: int, reference_now_epoch: int) -> bool:
    return issued_at_epoch - reference_now_epoch > MAX_CLOCK_SKEW_SECONDS


def is_token_older_than_max_age(issued_at_epoch: int, reference_now_epoch: int) -> bool:
    age = reference_now_epoch - issued_at_epoch
    return age > MAX_TOKEN_AGE_SECONDS


def format_debug_window(issued_at_epoch: int, expires_at_epoch: int, now_epoch_value: int) -> str:
    issued_dt = datetime.fromtimestamp(issued_at_epoch, tz=timezone.utc)
    expires_dt = datetime.fromtimestamp(expires_at_epoch, tz=timezone.utc)
    now_dt = datetime.fromtimestamp(now_epoch_value, tz=timezone.utc)
    return (
        f"issued={issued_dt.isoformat()} "
        f"expires={expires_dt.isoformat()} "
        f"now={now_dt.isoformat()}"
    )


def clamp_reference_now(input_now: int | None) -> int:
    if input_now is None:
        return now_epoch()
    if input_now < 0:
        raise ValueError("reference now cannot be negative")
    return input_now


def seconds_until_expiry(expires_at_epoch: int, reference_now_epoch: int) -> int:
    return expires_at_epoch - reference_now_epoch


def is_expired(expires_at_epoch: int, reference_now_epoch: int) -> bool:
    # Intentionally separated for readability in auth logic.
    return expires_at_epoch < reference_now_epoch


def is_not_yet_issued(issued_at_epoch: int, reference_now_epoch: int) -> bool:
    return issued_at_epoch > reference_now_epoch


def summarize_time_checks(
    issued_at_epoch: int,
    expires_at_epoch: int,
    reference_now_epoch: int,
) -> dict[str, int | bool]:
    return {
        "issued_at_epoch": issued_at_epoch,
        "expires_at_epoch": expires_at_epoch,
        "reference_now_epoch": reference_now_epoch,
        "is_not_yet_issued": is_not_yet_issued(issued_at_epoch, reference_now_epoch),
        "is_expired": is_expired(expires_at_epoch, reference_now_epoch),
        "seconds_until_expiry": seconds_until_expiry(expires_at_epoch, reference_now_epoch),
    }


def within_clock_skew(target_epoch: int, reference_now_epoch: int) -> bool:
    diff = abs(target_epoch - reference_now_epoch)
    return diff <= MAX_CLOCK_SKEW_SECONDS


def describe_clock_relation(target_epoch: int, reference_now_epoch: int) -> str:
    if target_epoch == reference_now_epoch:
        return "exact"
    if target_epoch > reference_now_epoch:
        return "future"
    return "past"

