from __future__ import annotations

from typing import Any

from models import TokenRecord, record_from_payload, to_public_dict


class InMemoryTokenStore:
    def __init__(self) -> None:
        self._records: dict[str, TokenRecord] = {}

    def upsert_payload(self, payload: dict[str, Any]) -> TokenRecord:
        record = record_from_payload(payload)
        self._records[record.token_id] = record
        return record

    def get(self, token_id: str) -> TokenRecord | None:
        key = token_id.strip()
        if not key:
            return None
        return self._records.get(key)

    def revoke(self, token_id: str) -> bool:
        record = self.get(token_id)
        if record is None:
            return False
        if record.revoked:
            return True
        updated_payload = to_public_dict(record)
        updated_payload["revoked"] = True
        self._records[token_id.strip()] = record_from_payload(updated_payload)
        return True

    def clear(self) -> None:
        self._records.clear()

    def list_for_user(self, user_id: str) -> list[TokenRecord]:
        uid = user_id.strip()
        if not uid:
            return []
        return [record for record in self._records.values() if record.user_id == uid]

    def count(self) -> int:
        return len(self._records)


def seed_store_with_examples(store: InMemoryTokenStore) -> None:
    examples = [
        {
            "token_id": "tok-demo-1",
            "user_id": "user-1",
            "issued_at_epoch": 1700000000,
            "expires_at_epoch": 1700003600,
            "revoked": False,
            "audience": "api",
            "scope": "read",
        },
        {
            "token_id": "tok-demo-2",
            "user_id": "user-2",
            "issued_at_epoch": 1700001000,
            "expires_at_epoch": 1700004600,
            "revoked": True,
            "audience": "api",
            "scope": "write",
        },
    ]
    for payload in examples:
        store.upsert_payload(payload)


def export_user_tokens(store: InMemoryTokenStore, user_id: str) -> list[dict[str, Any]]:
    records = store.list_for_user(user_id)
    return [to_public_dict(record) for record in records]


def load_bulk(store: InMemoryTokenStore, payloads: list[dict[str, Any]]) -> dict[str, int]:
    accepted = 0
    rejected = 0
    for payload in payloads:
        try:
            store.upsert_payload(payload)
            accepted += 1
        except ValueError:
            rejected += 1
    return {"accepted": accepted, "rejected": rejected}

