    records = store.list_for_user(user_id)
    return [to_public_dict(record) for record in records]


def load_bulk(store: InMemoryTokenStore, payloads: list[dict[str, Any]]) -> dict[str, int]:
    accepted = 0
    rejected = 0
    for payload in payloads:
        try:
            store.upsert_payload(payload)
            accepted += 1
        except ValueError:
            rejected += 1
    return {"accepted": accepted, "rejected": rejected}
